mapper.select:
SELECT id, created_by_user_id AS createdByUserId, group_id AS groupId, name, link_code AS linkCode, code_type AS codeType, full_url AS fullUrl, sort_order AS sortOrder, short_domain_id AS shortDomainId, status, disabled_reason_code AS disabledReasonCode, expires_at AS expiresAt, revision, created_at AS createdAt, updated_at AS updatedAt FROM t_link WHERE deleted_at IS NULL
AND created_by_user_id = #{criteria.createdByUserId}
AND short_domain_id = #{criteria.shortDomainId}
AND status = #{criteria.status}
AND ( POSITION(lower(#{criteria.searchTerm}) IN lower(name)) > 0 OR POSITION(lower(#{criteria.searchTerm}) IN lower(link_code)) > 0 OR POSITION(lower(#{criteria.searchTerm}) IN lower(full_url)) > 0 )
AND (created_at, id) < (#{criteria.cursorCreatedAt}, #{criteria.cursorId})
ORDER BY created_at DESC, id DESC LIMIT #{criteria.fetchSize}
